    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10*1000=10000, VAT 21% = 2100
  // Line 2: 100*37=3700, VAT 9% = 333
  // Subtotal: 13700, VAT: 2433, Total: 16133
  assert.equal(totals.subtotal, 13700);
  assert.equal(totals.vat, 2433);
  assert.equal(totals.total, 16133);
});

test('invoiceTotals with multiple lines and discounts and VAT', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 10 },
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 10*9500=95000, discount 10%=9500, after discount=85500, VAT 21%=17955
  // Line 2: 5*8500=42500, discount 5%=2125, after discount=40375, VAT 21%=8479 (rounded)
  // Subtotal: 137500, Discount: 11625, VAT: 26434, Total: 152309
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.discount, 11625);
  assert.equal(totals.vat, 26434);
  assert.equal(totals.total, 152309);
});

test('invoiceTotals clamps negative total to 0 even with VAT', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 200 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 10000, Discount: 20000, VAT would be negative but clamped
  // After discount: -10000 (clamped to 0)
  // VAT on 0: 0
  // Total clamped to 0
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 20000);
  assert.equal(totals.total, 0);
});

